/**
 * Runs Jcreate++ generated Cluster Script on the `$` mock.
 *
 * Contract:
 * - Only code generated by Jcreate++ is executed (Function is not a sandbox).
 * - Every name the code may reference is passed explicitly; nothing is added to globals.
 * - Math.random is replaced per runner with a seeded generator; the global Math is untouched.
 * - An exception inside a callback is recorded and stops only that callback invocation.
 * - After the program changes, create a new runner instead of reusing state.
 */

import { createClusterMock, type ClusterMock, type Handle } from './clusterMock';
import { Quaternion, Vector3 } from './math';

export type RunnerOptions = {
  seed?: number;
  position?: Vector3;
  rotation?: Quaternion;
};

export type Runner = ClusterMock & {
  /** Seconds simulated so far. */
  time: number;
  start(): void;
  update(deltaTime: number): void;
  /** Advance by `seconds` using a fixed frame time (default 1/60). */
  advance(seconds: number, deltaTime?: number): void;
  interact(player?: Handle): void;
  grab(isGrab: boolean, player?: Handle): void;
  collide(handle?: Handle | null): void;
  receive(message: string, arg?: unknown, sender?: Handle | null): void;
  ride(isGetOn: boolean, player?: Handle): void;
  steer(input: { x: number; y: number }, player?: Handle): void;
  steerAdditionalAxis(input: number, player?: Handle): void;
  errors(): string[];
};

/** mulberry32 */
function seededRandom(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function createRunner(code: string, options: RunnerOptions = {}): Runner {
  const mock = createClusterMock({ position: options.position, rotation: options.rotation });
  const math = Object.create(Math) as Math;
  math.random = seededRandom(options.seed ?? 1);

  // Generated code is a plain script; pass the Cluster globals it may reference.
  const program = new Function('$', 'Vector3', 'Quaternion', 'Math', code);
  program(mock.$, Vector3, Quaternion, math);

  const defaultPlayer = mock.createHandle('player', 'player1');
  let pending = 0;

  const call = (event: string, fn: (() => void) | undefined) => {
    if (!fn) return;
    try {
      fn();
    } catch (e) {
      mock.log.push({ type: 'error', event, message: `${(e as Error).name}: ${(e as Error).message}` });
    }
  };

  const runner: Runner = {
    ...mock,
    time: 0,
    start() {
      call('start', mock.handlers.start && (() => mock.handlers.start!()));
    },
    update(deltaTime) {
      runner.time += deltaTime;
      call('update', mock.handlers.update && (() => mock.handlers.update!(deltaTime)));
    },
    advance(seconds, deltaTime = 1 / 60) {
      // Whole frames only; the remainder carries over to the next advance() call.
      pending += seconds;
      while (pending >= deltaTime - 1e-9) {
        pending -= deltaTime;
        runner.update(deltaTime);
      }
    },
    ride(isGetOn, player = defaultPlayer) {
      call('ride', mock.handlers.ride && (() => mock.handlers.ride!(isGetOn, player)));
    },
    steer(input, player = defaultPlayer) {
      call('steer', mock.handlers.steer && (() => mock.handlers.steer!(input, player)));
    },
    steerAdditionalAxis(input, player = defaultPlayer) {
      call('steerAdditionalAxis', mock.handlers.steerAdditionalAxis && (() => mock.handlers.steerAdditionalAxis!(input, player)));
    },
    interact(player = defaultPlayer) {
      call('interact', mock.handlers.interact && (() => mock.handlers.interact!(player)));
    },
    grab(isGrab, player = defaultPlayer) {
      call('grab', mock.handlers.grab && (() => mock.handlers.grab!(isGrab, false, player)));
    },
    collide(handle = mock.createHandle('item', 'other')) {
      call('collide', mock.handlers.collide && (() => mock.handlers.collide!({ handle })));
    },
    receive(message, arg = null, sender = mock.createHandle('item', 'sender')) {
      call('receive', mock.handlers.receive && (() => mock.handlers.receive!(message, arg, sender)));
    },
    errors() {
      return mock.log.filter((l) => l.type === 'error').map((l) => (l as { event: string; message: string }).event + ': ' + (l as { message: string }).message);
    },
  };
  return runner;
}
